def record(trail, action, shelf_code, sku, qty):
    trail.append(f"{len(trail) + 1:02d} {action:<8} {shelf_code} {sku} {qty:+d}")


def recount(shelf, sku, counted, trail):
    before = shelf.on_hand.get(sku, 0)
    if counted <= 0:
        shelf.on_hand.pop(sku, None)
    else:
        shelf.on_hand[sku] = counted
    if shelf.held.get(sku, 0) > max(counted, 0):
        if counted > 0:
            shelf.held[sku] = counted
        else:
            shelf.held.pop(sku, None)
    record(trail, "recount", shelf.code, sku, max(counted, 0) - before)


def check_holds(shelf, open_orders):
    from stockroom import orders  # imported here: orders imports this module

    problems = []
    for sku in sorted(shelf.held):
        wanted = orders.wanted_by(open_orders, sku)
        if wanted != shelf.held[sku]:
            problems.append(f"{shelf.code} {sku}: {shelf.held[sku]} held, open orders want {wanted}")
    return problems

