import json

from stockroom.models import Order, Product
from stockroom.shelf import Shelf


class UnknownSku(Exception):
    pass


class UnknownOrder(Exception):
    pass


def read(path):
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def _product_from(row):
    return Product(row["sku"], row["name"], row["unit_price"], row["min_stock"], row["shelf"])


def _order_from(row):
    return Order(row["id"], row["customer"], row["tier"], row["status"], tuple((s, q) for s, q in row["lines"]))


def products(data):
    return [_product_from(row) for row in data["products"]]


def product(data, sku):
    for row in data["products"]:
        if row["sku"] == sku:
            return _product_from(row)
    raise UnknownSku(sku)


def shelves(data):
    return [Shelf(row["code"], row["capacity"], row["on_hand"], row["held"]) for row in data["shelves"]]


def shelf_for(data, all_shelves, sku):
    code = product(data, sku).shelf
    for shelf in all_shelves:
        if shelf.code == code:
            return shelf
    raise UnknownSku(sku)


def orders(data):
    return [_order_from(row) for row in data["orders"]]


def open_orders(data):
    return [o for o in orders(data) if o.status == "open"]


def order(data, order_id):
    for o in orders(data):
        if o.id == order_id:
            return o
    raise UnknownOrder(str(order_id))


def tier_rate(data, tier):
