from stockroom import audit


class Shortage(Exception):
    pass


def wanted_by(open_orders, sku):
    return sum(qty for o in open_orders for s, qty in o.lines if s == sku)


def reserve(shelf, sku, qty, trail):
    free = shelf.on_hand.get(sku, 0) - shelf.held.get(sku, 0)
    if qty > free:
        raise Shortage(f"{sku}: wanted {qty}, {free} free on shelf {shelf.code}")
    shelf.held[sku] = shelf.held.get(sku, 0) + qty
    audit.record(trail, "hold", shelf.code, sku, qty)


def release(shelf, sku, qty, trail):
    left = shelf.held.get(sku, 0) - qty
    if left > 0:
        shelf.held[sku] = left
    else:
        shelf.held.pop(sku, None)
    audit.record(trail, "release", shelf.code, sku, -qty)


def ship(shelf, sku, qty, trail):
    if qty > shelf.on_hand.get(sku, 0):
        raise Shortage(f"{sku}: wanted {qty}, {shelf.on_hand.get(sku, 0)} on shelf {shelf.code}")
    shelf.on_hand[sku] = shelf.on_hand[sku] - qty
    if shelf.on_hand[sku] <= 0:
        del shelf.on_hand[sku]
    left = shelf.held.get(sku, 0) - qty
    if left > 0:
        shelf.held[sku] = left
    else:
        shelf.held.pop(sku, None)
    audit.record(trail, "ship", shelf.code, sku, -qty)

