from stockroom.pricing import discounts


def round_money(amount):
    return round(amount + 1e-9, 2)


def base_price(product, qty):
    return product.unit_price * qty


def line_total(product, qty, tier_rate):
    gross = base_price(product, qty)
    off = discounts.volume_discount(product, qty) + discounts.tier_discount(gross, tier_rate)
    off = min(off, discounts.cap(product, qty))
    return round_money(gross - off)


def order_total(lines):
    return round_money(sum(lines))

