from stockroom import audit, db
from stockroom.pricing import round_money
from stockroom.textfmt import money, table


def stock_rows(data, all_shelves):
    rows = [("shelf", "sku", "name", "on hand", "held", "free")]
    for shelf in all_shelves:
        for sku in sorted(shelf.on_hand):
            held = shelf.held.get(sku, 0)
            rows.append((shelf.code, sku, db.product(data, sku).name, shelf.on_hand[sku], held, shelf.on_hand[sku] - held))
    return rows


def low_stock(data, all_shelves):
    low = []
    for p in db.products(data):
        shelf = db.shelf_for(data, all_shelves, p.sku)
        free = shelf.on_hand.get(p.sku, 0) - shelf.held.get(p.sku, 0)
        if free < p.min_stock:
            low.append((p.sku, p.name, free, p.min_stock))
    return low


def stock_value(data, all_shelves):
    total = 0.0
    for shelf in all_shelves:
        for sku, qty in shelf.on_hand.items():
            total += db.product(data, sku).unit_price * qty
    return round_money(total)


def summary(data, all_shelves):
    lines = [f"stock value: {money(stock_value(data, all_shelves))}"]
    for shelf in all_shelves:
        lines.append(f"shelf {shelf.code}: {shelf.total()} of {shelf.capacity} in use, {shelf.free_space()} free")
    low = low_stock(data, all_shelves)
    lines.append(f"low stock: {len(low)}")
    if low:
        lines.append(table([(sku, name, f"{free} free", f"min {minimum}") for sku, name, free, minimum in low]))
    problems = [p for shelf in all_shelves for p in audit.check_holds(shelf, db.open_orders(data))]
    lines.append(f"hold problems: {len(problems)}")
    lines.extend(problems)
    return "\n".join(lines)

