class ShelfFull(Exception):
    pass


class Shelf:
    def __init__(self, code, capacity, on_hand=None, held=None):
        self.code = code
        self.capacity = capacity
        self.on_hand = dict(on_hand or {})
        self.held = dict(held or {})

    def receive(self, sku, qty):
        if qty <= 0:
            raise ValueError("quantity must be positive")
        if self.total() + qty > self.capacity:
            raise ShelfFull(f"shelf {self.code} holds {self.capacity}, {self.total()} in use")
        self.on_hand[sku] = self.on_hand.get(sku, 0) + qty

    def total(self):
        return sum(self.on_hand.values())

    def free_space(self):
        return self.capacity - self.total()

