def money(amount):
    return f"{amount:,.2f}"


def _widths(rows):
    return [max(len(str(row[i])) for row in rows) for i in range(len(rows[0]))]


def table(rows):
    if not rows:
        return ""
    widths = _widths(rows)
    return "\n".join("  ".join(str(cell).ljust(w) for cell, w in zip(row, widths)).rstrip() for row in rows)

