from stockroom import pricing
from stockroom.models import Product

TEA = Product("TEA-250", "Green tea 250 g", 6.4, 40, "A1")


class PricingTest(unittest.TestCase):
    def test_small_order_pays_list_price(self):
        self.assertEqual(pricing.line_total(TEA, 5, 0.0), 32.0)

    def test_volume_and_tier_discounts_add_up(self):
        self.assertEqual(pricing.line_total(TEA, 20, 0.05), 117.76)

    def test_discount_is_capped(self):
        self.assertEqual(pricing.line_total(TEA, 50, 0.1), 272.0)


if __name__ == "__main__":
    unittest.main()
